if max(p1, p2) >= 4 and abs(p1 - p2) >= 2:
    # Check if game would have ended earlier (invalid state)
    if (min(p1, p2) < 3 and max(p1, p2) > 4) or (min(p1, p2) >= 3 and abs(p1 - p2) > 2):
        raise ValueError("game would have already ended")
    return "Game Player 1" if p1 > p2 else "Game Player 2"
# Deuce and advantage
if p1 >= 3 and p2 >= 3:
    if p1 == p2:
        return "Deuce"
    return "Advantage Player 1" if p1 > p2 else "Advantage Player 2"
# Regular scores - equal scores use "-All" format
